function q(concept:string, topic:string, subject:string, system:string, difficulty:number, ref:string, stem:string, options:[string,string][], explanation:string, objective:string, closest:string): ExpansionSpec {
 return {code:`op26x-${String(nextCode++).padStart(4,'0')}`,concept, reasoning:tags[difficulty-1]!, difficultyReason:`${tags[difficulty-1]}: ${objective} The stated findings and alternatives define this demand.`, evidenceNote:`Publisher identity and relevant guidance/resource checked during authoring. ${references[ref]![0]} supports the clinical domain; this item is original prose and is not expert validated.`, semanticReviewNote:`Closest baseline concept: ${closest}. Distinct decision: ${objective}`, concerns:[], question:{subject,system,topic,difficulty,exam:'Step 2 CK',stem,options,explanation,objective,reference:references[ref]!} satisfies Spec};
}
